(()=>{
 const root=document.querySelector('[data-lab^="f-"]');if(!root)return;const kind=root.dataset.lab;
 const tx=(x,y,t,a='start',extra='')=>`<text x="${x}" y="${y}" text-anchor="${a}" ${extra}>${t}</text>`;
 const ln=(d,on=false)=>`<path d="${d}" fill="none" stroke="${on?'var(--primary)':'var(--foreground)'}" stroke-width="${on?2.3:1.5}"/>`;
 const rect=(x,y,w,h,on=false)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${on?'var(--accent)':'none'}" stroke="var(--border)" stroke-width="1.3"/>`;
 const bits=(n,w)=>n.toString(2).padStart(w,'0'),bounded=(v,a,b)=>Math.max(a,Math.min(b,Math.floor(+v||0)));
 const gate=(x,y,type,scale=1)=>{const base=type.replace('n',''),inv=['nand','nor','xnor','not'].includes(type),isOr=['or','nor','xor','xnor'].includes(type);let p;
  if(type==='not')p='<path d="M0 -21 L40 0 L0 21 Z"/>';
  else if(isOr)p='<path d="M0 -23 Q24 -23 44 0 Q24 23 0 23 Q13 0 0 -23 Z"/>'+(['xor','xnor'].includes(type)?'<path d="M-6 -23 Q7 0 -6 23"/>':'');
  else p='<path d="M0 -23 H22 A23 23 0 0 1 22 23 H0 Z"/>';
  return `<g transform="translate(${x} ${y}) scale(${scale})" fill="none" stroke="var(--foreground)" stroke-width="1.6">${p}${inv?'<path d="M'+(type==='not'?40:isOr?44:45)+' 0 H46"/><circle cx="50" cy="0" r="4" fill="var(--background)"/>':''}</g>`;
 };
 let s={...(window.openai?.widgetState?.privateContent||{})},render,svg;
 const save=()=>window.openai?.setWidgetState({modelContent:{topic:kind,...s},privateContent:s}).catch(()=>{});
 const commit=()=>{render();save();};
 const shell=(controls,aria)=>{root.innerHTML=controls+`<svg role="img" aria-label="${aria}"></svg><div class="lab-status" aria-live="polite"></div>`;svg=root.querySelector('svg');};
 const draw=(w,h,o,data={})=>{svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=o;Object.assign(svg.dataset,data);};
 const status=t=>root.querySelector('.lab-status').textContent=t;
 const bitButtons=(letters)=>'<div class="lab-buttons">'+letters.map(k=>`<button type="button" data-input="${k}" aria-pressed="false">${k}=0</button>`).join('')+'</div>';
 const syncButtons=()=>root.querySelectorAll('[data-input]').forEach(b=>{b.textContent=b.dataset.input+'='+s[b.dataset.input];b.setAttribute('aria-pressed',!!s[b.dataset.input]);});
 if(kind==='f-place'){
  s={raw:173,...s};shell('<div class="lab-buttons">'+Array.from({length:8},(_,i)=>`<button data-place="${7-i}" type="button">切换第${i+1}位</button>`).join('')+'</div>','二进制每位的权与总值');
  render=()=>{let w=svg.clientWidth||320,cw=(w-20)/4,o='<title>整数与小数位权</title>';for(let i=0;i<8;i++){let row=Math.floor(i/4),col=i%4,x=10+col*cw,y=38+row*124,weight=2**(3-i),v=(s.raw>>(7-i))&1;o+=rect(x,y,cw-5,94,!!v)+tx(x+(cw-5)/2,y+22,i<4?'整数位':'小数位','middle')+tx(x+(cw-5)/2,y+49,v,'middle','font-size="23"')+tx(x+(cw-5)/2,y+77,'权 '+(i<4?weight:'1/'+2**(i-3)),'middle');}
   const value=s.raw/16;o+=tx(w/2,324,bits(s.raw>>4,4)+'.'+bits(s.raw&15,4)+'₂ = '+value,'middle');draw(w,350,o,{value,raw:s.raw});root.querySelectorAll('[data-place]').forEach(b=>{const i=+b.dataset.place;b.textContent=(i>=4?'整数':'小数')+' '+(i>=4?'2^'+(i-4):'2^'+(i-4))+' = '+((s.raw>>i)&1);b.setAttribute('aria-pressed',!!((s.raw>>i)&1));});status('整数最高位权8，小数最低位权1/16；各位贡献相加。');};
  root.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{s.raw^=1<<+b.dataset.place;commit();});
 }else if(kind==='f-complement'){
  s={value:-13,...s};shell('<label class="range-label">真值（8位，总位数含符号位）<input data-value type="range" min="-128" max="127" value="-13"></label>','原码反码补码对照');
  render=()=>{s.value=bounded(s.value,-128,127);let v=s.value,w=svg.clientWidth||320,cw=(w-24)/8,mag=Math.abs(v),original=v===-128?null:(v<0?128:0)+mag,inverse=v===-128?null:v<0?255-mag:v,complement=(v+256)%256,o='<title>8位编码比较</title>'+tx(w/2,24,'真值 '+v+' · 最高位为符号位','middle');
   for(const [i,label,val] of [[0,'原码',original],[1,'反码',inverse],[2,'补码',complement]]){let y=60+i*105;o+=tx(12,y,label);if(val===null)o+=tx(w/2,y+45,'8位原码/反码不能表示−128','middle');else for(let b=0;b<8;b++){let x=12+b*cw,on=(val>>(7-b))&1;o+=rect(x,y+15,cw-3,48,!!on)+tx(x+(cw-3)/2,y+46,on,'middle');}}
   o+=tx(w/2,401,'补码无符号读数 '+complement,'middle')+tx(w/2,427,v<0?complement+' − 256 = '+v:'最高位0，直接读为 '+v,'middle');draw(w,454,o,{value:v,original:original===null?'unrepresentable':bits(original,8),inverse:inverse===null?'unrepresentable':bits(inverse,8),complement:bits(complement,8)});root.querySelector('[data-value]').value=v;status(v===-128?'−128的正相反数+128不能用8位有符号补码表示。':v<0?'从负数原码出发，只翻转数值位；从正绝对值位串出发，则全部位取反加1。':'正数三种编码一致；0在本模型中采用正零。');};root.querySelector('[data-value]').oninput=e=>{s.value=+e.target.value;commit();};
 }else if(kind==='f-addition'){
  s={a:13,b:10,...s};shell('<div class="lab-controls"><label>加数A（−32至31）<input data-a type="number" min="-32" max="31" value="13"></label><label>加数B（−32至31）<input data-b type="number" min="-32" max="31" value="10"></label></div>','6位补码逐列加法和溢出');
  render=()=>{s.a=bounded(s.a,-32,31);s.b=bounded(s.b,-32,31);const a=(s.a+64)%64,b=(s.b+64)%64,total=a+b,res=total%64,decoded=res>=32?res-64:res,overflow=s.a+s.b< -32||s.a+s.b>31,w=svg.clientWidth||320,cw=(w-90)/6,start=75;let carries=[0];for(let i=0;i<6;i++)carries.push((((a>>i)&1)+((b>>i)&1)+carries[i])>>1);let o='<title>六位补码加法</title>'+tx(w/2,24,'数学真值：'+s.a+' + ('+s.b+') = '+(s.a+s.b),'middle');
   o+=tx(9,74,'进位入列')+tx(9,128,'A')+tx(9,179,'+ B')+tx(9,247,'结果');for(let col=0;col<6;col++){let bit=5-col,x=start+(col+.5)*cw;o+=tx(x,74,carries[bit],'middle')+tx(x,128,(a>>bit)&1,'middle','font-size="20"')+tx(x,179,(b>>bit)&1,'middle','font-size="20"')+tx(x,247,(res>>bit)&1,'middle','font-size="20"');}o+=ln(`M 62 203 H ${w-10}`)+tx(w/2,297,'第7位进位（舍弃）='+carries[6],'middle')+tx(w/2,326,'保留6位按补码读 = '+decoded,'middle')+tx(w/2,355,'有符号溢出：'+(overflow?'有':'无'),'middle');draw(w,382,o,{a:s.a,b:s.b,result:bits(res,6),decoded,carry:carries[6],overflow});for(const k of ['a','b'])root.querySelector('[data-'+k+']').value=s[k];status(overflow?'数学结果超出−32至31；位串是模64结果，不能当精确有符号答案。':'数学结果在6位补码范围内，进位与溢出分别判断。');};for(const k of ['a','b'])root.querySelector('[data-'+k+']').onchange=e=>{s[k]=+e.target.value;commit();};
 }else if(kind==='f-codes'){
  s={value:59,...s};shell('<label class="range-label">十进制数（0—99）<input data-value type="range" min="0" max="99" value="59"></label>','普通二进制与逐位十进制编码');
  render=()=>{s.value=bounded(s.value,0,99);let w=svg.clientWidth||320,digits=[Math.floor(s.value/10),s.value%10],bcd=digits.map(d=>bits(d,4)),excess=digits.map(d=>bits(d+3,4)),o='<title>码制不同，解释不同</title>'+tx(w/2,25,'十进制真值 '+s.value,'middle');for(const [i,label,value] of [[0,'普通二进制（8位补零显示）',bits(s.value,8)],[1,'8421：十位数字、个位数字',bcd.join('  ')],[2,'余3：每个数字分别加3',excess.join('  ')]]){let y=64+i*104;o+=tx(10,y,label)+rect(10,y+13,w-20,51)+tx(w/2,y+46,value,'middle','font-size="21"');}draw(w,387,o,{value:s.value,binary:bits(s.value,8),bcd:bcd.join(''),excess:excess.join('')});root.querySelector('[data-value]').value=s.value;status('BCD和余3码保留前导十位0，方便逐组比较；每组四位只表示一个十进制数字。');};root.querySelector('[data-value]').oninput=e=>{s.value=+e.target.value;commit();};
 }else if(kind==='f-gates'){
  s={A:1,B:0,...s};shell(bitButtons(['A','B']),'七种逻辑门的符号与当前输出');
  render=()=>{let w=svg.clientWidth||320,o='<title>基本门与复合门</title>',values={and:s.A&s.B,or:s.A|s.B,not:1-s.A,nand:1-(s.A&s.B),nor:1-(s.A|s.B),xor:s.A^s.B,xnor:1-(s.A^s.B)},labels={and:'与 AB',or:'或 A+B',not:'非 A′',nand:'与非 (AB)′',nor:'或非 (A+B)′',xor:'异或 A⊕B',xnor:'同或 AB+A′B′'};let x=w/2-12;
   Object.keys(values).forEach((k,i)=>{let y=50+i*99,not=k==='not',inv=['nand','nor','xnor','not'].includes(k);o+=tx(w/2,y-32,labels[k],'middle')+gate(x,y,k)+tx(8,y-20,'A='+s.A)+ln(`M 8 ${y-(not?0:13)} H ${x+3}`,!!s.A);if(!not)o+=tx(8,y+39,'B='+s.B)+ln(`M 8 ${y+13} H ${x+3}`,!!s.B);o+=ln(`M ${x+(inv?54:45)} ${y} H ${w-8}`,!!values[k])+tx(w-8,y-8,'Y='+values[k],'end');});draw(w,718,o,{values:JSON.stringify(values)});syncButtons();status('非门只使用A；异或为两输入不同，同或为两输入相同。');};root.querySelectorAll('[data-input]').forEach(b=>b.onclick=()=>{s[b.dataset.input]^=1;commit();});
 }else if(kind==='f-represent'){
  s={A:1,B:0,C:1,...s};shell(bitButtons(['A','B','C']),'裁判函数的门电路与完整理想波形');
  render=()=>{let w=svg.clientWidth||320,orX=75,andX=w-100,m=s.B|s.C,y=s.A&m,a=s.A*4+s.B*2+s.C,o='<title>Y=A(B+C)</title>'+tx(w/2,22,'X=B+C，Y=A·X','middle')+tx(8,64,'A='+s.A)+ln(`M 8 72 H ${andX+3}`,!!s.A)+tx(8,130,'B='+s.B)+tx(8,188,'C='+s.C)+ln(`M 8 139 H ${orX+3}`,!!s.B)+ln(`M 8 165 H ${orX+3}`,!!s.C)+gate(orX,152,'or')+ln(`M ${orX+45} 152 H ${andX-15} V 97 H ${andX+3}`,!!m)+gate(andX,85,'and')+ln(`M ${andX+45} 85 H ${w-8}`,!!y)+tx(w-8,72,'Y='+y,'end')+tx(w/2,226,'所选真值表行 '+bits(a,3)+'：Y='+y,'middle');
   let left=35,step=(w-left-8)/8,table=Array.from({length:8},(_,i)=>((i&4)&&((i&2)||(i&1)))?1:0);o+=`<rect x="${left+a*step}" y="251" width="${step}" height="266" fill="var(--accent)"/>`;['A','B','C','Y'].forEach((k,row)=>{let top=275+row*65;o+=tx(9,top+12,k);let values=Array.from({length:8},(_,i)=>row<3?((i>>(2-row))&1):table[i]),d='';values.forEach((v,i)=>{let x=left+i*step,z=top+(v?0:26);d+=(i?' L':'M')+' '+x+' '+z+' H '+(x+step);});o+=ln(d,row===3);});for(let i=0;i<8;i++)o+=tx(left+(i+.5)*step,539,bits(i,3),'middle','font-size="10"');draw(w,563,o,{address:a,output:y,table:JSON.stringify(table)});syncButtons();status('枚举所有输入，零延迟；绿色背景标出当前输入组合所在的区间。');};root.querySelectorAll('[data-input]').forEach(b=>b.onclick=()=>{s[b.dataset.input]^=1;commit();});
 }else if(kind==='f-kmap'){
  const defs={corners:{title:'跨边界四角',ones:[0,2,8,10],xs:[],groups:[[0,2,8,10]],answer:'F=B′D′'},overlap:{title:'重叠覆盖',ones:[0,2,4,6,10,14],xs:[],groups:[[0,2,4,6],[2,6,10,14]],answer:'F=A′D′+CD′'},dc:{title:'BCD无关项',ones:[8,9],xs:[10,11,12,13,14,15],groups:[[8,9,10,11,12,13,14,15]],answer:'F=A（有效BCD输入域内）'},zero:{title:'圈0，先求F′',ones:Array.from({length:16},(_,i)=>i).filter(i=>![0,1,4,5].includes(i)),xs:[],groups:[[0,1,4,5]],answer:'F′=A′C′；F=A+C'},free:{title:'自由填图',ones:[],xs:[],groups:[],answer:'填图练习，不自动求最简式'}};
  s={preset:'corners',cells:Array(16).fill(0),...s};if(!defs[s.preset])s.preset='corners';shell('<div class="lab-controls"><label>图中示例<select data-preset>'+Object.entries(defs).map(([k,d])=>`<option value="${k}">${d.title}</option>`).join('')+'</select></label></div><div class="lab-buttons"><button type="button" data-reset>清空练习图</button></div>','四变量卡诺图及合法分组');svg.setAttribute('role','group');
  render=()=>{const d=defs[s.preset],w=svg.clientWidth||320,left=47,top=77,cw=(w-left-14)/4,ch=62,order=[0,1,3,2],values=s.preset==='free'?s.cells:Array.from({length:16},(_,i)=>d.xs.includes(i)?'X':+d.ones.includes(i));let o='<title>AB行，CD列的四变量卡诺图</title>'+tx(9,25,'行AB / 列CD')+tx(w/2,50,d.title,'middle');for(let i=0;i<4;i++){o+=tx(left+(i+.5)*cw,top-9,bits(order[i],2),'middle')+tx(32,top+i*ch+35,bits(order[i],2),'end');for(let j=0;j<4;j++){const address=order[i]*4+order[j],x=left+j*cw,y=top+i*ch,v=values[address];o+=`<g data-cell="${address}"${s.preset==='free'?' role="button" tabindex="0" aria-label="最小项'+address+'，当前'+v+'，切换"':''}>`+rect(x,y,cw,ch,v===1)+tx(x+7,y+15,'m'+address,'start','font-size="10"')+tx(x+cw/2,y+43,v,'middle','font-size="20"')+'</g>';}}
   d.groups.forEach((group,k)=>{const color=k?'var(--viz-series-2)':'var(--primary)',inset=5+k*5,rows=order.map((v,i)=>group.some(a=>Math.floor(a/4)===v)?i:-1).filter(i=>i>=0),cols=order.map((v,i)=>group.some(a=>a%4===v)?i:-1).filter(i=>i>=0),runs=items=>{let r=[];for(const n of items){const last=r[r.length-1];if(last&&last[1]+1===n)last[1]=n;else r.push([n,n]);}return r;};for(const [r0,r1] of runs(rows))for(const [c0,c1] of runs(cols))o+=`<rect x="${left+c0*cw+inset}" y="${top+r0*ch+inset}" width="${(c1-c0+1)*cw-2*inset}" height="${(r1-r0+1)*ch-2*inset}" rx="5" stroke="${color}" fill="none" stroke-width="2"${k?' stroke-dasharray="5 3"':''}/>`;});
   o+=tx(w/2,369,d.answer,'middle');if(s.preset==='corners')o+=tx(w/2,399,'同色四角合计4格，是同一个跨边界组','middle');else if(s.preset==='overlap')o+=tx(w/2,399,'实线组与虚线组共享m2、m6，允许重叠','middle');else if(s.preset==='dc')o+=tx(w/2,399,'8、9必须为1；10—15可选为1','middle');else if(s.preset==='zero')o+=tx(w/2,399,'合并0得到的是F′，最后要再取反','middle');else o+=tx(w/2,399,'点击格子，或聚焦后按空格 / 回车','middle');draw(w,429,o,{preset:s.preset,values:JSON.stringify(values),groups:JSON.stringify(d.groups)});root.querySelector('[data-preset]').value=s.preset;status(s.preset==='free'?'本练习用于核对最小项位置，不自动判断所填函数是否最简。':'行列都按00、01、11、10；边界线表示同组在平面上的分段。');};
  root.querySelector('[data-preset]').onchange=e=>{s.preset=e.target.value;commit();};root.querySelector('[data-reset]').onclick=()=>{s.preset='free';s.cells=Array(16).fill(0);commit();};const edit=a=>{if(s.preset!=='free')return;const v=s.cells[a];s.cells[a]=v===0?1:v===1?'X':0;commit();svg.querySelector('[data-cell="'+a+'"]').focus();};svg.addEventListener('click',e=>{const g=e.target.closest('[data-cell]');if(g)edit(+g.dataset.cell);});svg.addEventListener('keydown',e=>{const g=e.target.closest('[data-cell]');if(g&&[' ','Enter'].includes(e.key)){e.preventDefault();edit(+g.dataset.cell);}});
 }else if(kind==='f-forms'){
  s={A:1,B:0,C:1,mode:'sop',...s};shell('<div class="lab-controls"><label>实现方式<select data-mode><option value="sop">与或：AC+BC′</option><option value="nand">与非—与非</option><option value="nor">或非—或非</option></select></label></div>'+bitButtons(['A','B','C']),'同一函数的三种门电路实现');
  render=()=>{const w=svg.clientWidth||320,type=s.mode==='nand'?'nand':s.mode==='nor'?'nor':'and',last=s.mode==='nand'?'nand':s.mode==='nor'?'nor':'or',isNor=s.mode==='nor',ins=isNor?[['B',s.B,'C',s.C],['A',s.A,'C′',1-s.C]]:[['A',s.A,'C',s.C],['B',s.B,'C′',1-s.C]],raw=ins.map(v=>isNor?1-(v[1]|v[3]):s.mode==='nand'?1-(v[1]&v[3]):v[1]&v[3]),y=isNor?1-(raw[0]|raw[1]):s.mode==='nand'?1-(raw[0]&raw[1]):raw[0]|raw[1],x=80,end=w-90;let o='<title>与或及等价实现</title>'+tx(w/2,26,'F=AC+BC′，当前F='+y,'middle');ins.forEach((v,i)=>{const gy=95+i*116;o+=tx(8,gy-20,v[0]+'='+v[1])+ln(`M 8 ${gy-13} H ${x+3}`,!!v[1])+tx(8,gy+39,v[2]+'='+v[3])+ln(`M 8 ${gy+13} H ${x+3}`,!!v[3])+gate(x,gy,type)+ln(`M ${x+(type==='and'?45:54)} ${gy} H ${end-18} V ${i?166:140} H ${end+3}`,!!raw[i]);});o+=gate(end,153,last)+ln(`M ${end+(last==='or'?45:54)} 153 H ${w-8}`,!!y)+tx(w-8,138,'F='+y,'end')+tx(w/2,286,isNor?'F=((B+C)′+(A+C′)′)′':s.mode==='nand'?'F=((AC)′(BC′)′)′':'F=AC+BC′','middle')+tx(w/2,319,'C′由另一个反相器产生，此图省略','middle');draw(w,344,o,{output:y,mode:s.mode,A:s.A,B:s.B,C:s.C});root.querySelector('[data-mode]').value=s.mode;syncButtons();status(isNor?'先改为(B+C)(A+C′)，再两级或非。':s.mode==='nand'?'两次整体取反保持原函数，末级仍输出F。':'第一层形成两个乘积，第二层作或。');};root.querySelector('[data-mode]').onchange=e=>{s.mode=e.target.value;commit();};root.querySelectorAll('[data-input]').forEach(b=>b.onclick=()=>{s[b.dataset.input]^=1;commit();});
 }
 if(render){new ResizeObserver(render).observe(root);render();}
})();
